fn OwnedPayload(comptime T: type, comptime wipe: fn (*T) void) type {
    return struct {
        data: T,
        data_json: []u8,
        arena: std.heap.ArenaAllocator,

        pub fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
            wipe(&self.data);
            self.arena.deinit();
            @memset(self.data_json, 0);
            allocator.free(self.data_json);
        }
    };
}

