pub const AssistantMessage = struct {
    message_id: ?[]const u8 = null,
    model: ?[]const u8 = null,
    content: []const u8,
    tool_requests: ?[]const AssistantMessageToolRequest = null,
    reasoning_opaque: ?[]const u8 = null,
    reasoning_text: ?[]const u8 = null,
    reasoning_wire_field: ?[]const u8 = null,
    encrypted_content: ?[]const u8 = null,
    phase: ?[]const u8 = null,
    chunk_index: ?u64 = null,
    chunk_count: ?u64 = null,
    output_tokens: ?u64 = null,
    interaction_id: ?[]const u8 = null,
    request_id: ?[]const u8 = null,
    client_request_id: ?[]const u8 = null,
    service_request_id: ?[]const u8 = null,
    rte: ?bool = null,
    api_call_id: ?[]const u8 = null,
    server_tools: ?AssistantMessageServerTools = null,
    reasoning_blocks: ?AssistantMessageReasoningBlocks = null,
    turn_id: ?[]const u8 = null,
    parent_tool_call_id: ?[]const u8 = null,
    citations: ?Citations = null,
    fusion: ?FusionAttribution = null,
    raw: payloads.RawEvent = .{},
    arena: ?std.heap.ArenaAllocator = null,

    pub fn deinit(self: @This(), allocator: std.mem.Allocator) void {
        var owned = self;
        if (owned.arena) |*arena| {
            wipeAssistantMessageDataFields(&owned);
            arena.deinit();
        } else {
            freeAssistantMessageDataFields(&owned, allocator);
        }

        owned.raw.deinit(allocator);
    }
};

