pub const ExternalToolRequested = struct {
    request_id: []const u8,
    session_id: []const u8,
    tool_call_id: []const u8,
    tool_name: []const u8,
    provider_id: ?[]const u8,
    arguments: ?std.json.Value = null,
    working_directory: ?[]const u8 = null,
    traceparent: ?[]const u8 = null,
    tracestate: ?[]const u8 = null,
    arguments_json: []u8,
    raw: payloads.RawEvent = .{},
    arena: ?std.heap.ArenaAllocator = null,

    pub fn parseArguments(
        self: ExternalToolRequested,
        comptime T: type,
        allocator: std.mem.Allocator,
    ) !std.json.Parsed(T) {
        return std.json.parseFromSlice(T, allocator, self.arguments_json, .{
            .allocate = .alloc_always,
            .ignore_unknown_fields = true,
        });
    }

    pub fn deinit(self: @This(), allocator: std.mem.Allocator) void {
        var owned = self;
        if (owned.arena) |*arena| {
            wipeExternalToolRequestedDataFields(&owned);
            arena.deinit();
        } else {
            freeExternalToolRequestedDataFields(&owned, allocator);
        }
        @memset(self.arguments_json, 0);
        allocator.free(self.arguments_json);
        owned.raw.deinit(allocator);
    }
};

pub const PermissionRequested = struct {
    request_id: []const u8,
    permission_request: ?PermissionRequest = null,
    prompt_request: ?PermissionPromptRequest = null,
    agent_mode: ?SessionMode = null,
    risk_assessment: ?std.json.Value = null,
    resolved_by_hook: ?bool = null,
    permission_request_json: []u8,
    managed_approval_required: bool = false,
    automatic_handling: payloads.AutomaticPermissionHandling = .not_configured,
    raw: payloads.RawEvent = .{},
    arena: ?std.heap.ArenaAllocator = null,

    pub fn kind(self: PermissionRequested) !payloads.PermissionRequestKind {
        const parsed = try std.json.parseFromSlice(
            struct { kind: []const u8 },
            std.heap.page_allocator,
            self.permission_request_json,
            .{ .ignore_unknown_fields = true },
        );
        defer parsed.deinit();
        return payloads.PermissionRequestKind.fromString(parsed.value.kind);
    }

    pub fn parseRequest(
        self: PermissionRequested,
        comptime T: type,
        allocator: std.mem.Allocator,
    ) !std.json.Parsed(T) {
        return std.json.parseFromSlice(T, allocator, self.permission_request_json, .{
            .allocate = .alloc_always,
            .ignore_unknown_fields = true,
        });
    }

    pub fn deinit(self: @This(), allocator: std.mem.Allocator) void {
        var owned = self;
        if (owned.arena) |*arena| {
            wipePermissionRequestedDataFields(&owned);
            arena.deinit();
        } else {
            freePermissionRequestedDataFields(&owned, allocator);
        }
        @memset(self.permission_request_json, 0);
        allocator.free(self.permission_request_json);
        owned.raw.deinit(allocator);
    }
};

