fn parseAbortReason(_: std.mem.Allocator, value: std.json.Value) !AbortReason {
    const wire = try valueString(value);
    if (std.mem.eql(u8, wire, "user_initiated")) return .user_initiated;
    if (std.mem.eql(u8, wire, "remote_command")) return .remote_command;
    if (std.mem.eql(u8, wire, "user_abort")) return .user_abort;
    if (std.mem.eql(u8, wire, "autopilot_credit_limit")) return .autopilot_credit_limit;
    return error.InvalidSessionEvent;
}

