fn parseAttachment(allocator: std.mem.Allocator, value: std.json.Value) !Attachment {
    const object = try payloads.requiredObject(value);
    const discriminator = try payloads.requiredString(object, "type");
    if (std.mem.eql(u8, discriminator, "file")) return .{ .file = try parseAttachmentFile(allocator, value) };
    if (std.mem.eql(u8, discriminator, "directory")) return .{ .directory = try parseAttachmentDirectory(allocator, value) };
    if (std.mem.eql(u8, discriminator, "selection")) return .{ .selection = try parseAttachmentSelection(allocator, value) };
    if (std.mem.eql(u8, discriminator, "github_reference")) return .{ .github_reference = try parseAttachmentGitHubReference(allocator, value) };
    if (std.mem.eql(u8, discriminator, "github_commit")) return .{ .github_commit = try parseAttachmentGitHubCommit(allocator, value) };
    if (std.mem.eql(u8, discriminator, "github_release")) return .{ .github_release = try parseAttachmentGitHubRelease(allocator, value) };
    if (std.mem.eql(u8, discriminator, "github_actions_job")) return .{ .github_actions_job = try parseAttachmentGitHubActionsJob(allocator, value) };
    if (std.mem.eql(u8, discriminator, "github_repository")) return .{ .github_repository = try parseAttachmentGitHubRepository(allocator, value) };
    if (std.mem.eql(u8, discriminator, "github_file_diff")) return .{ .github_file_diff = try parseAttachmentGitHubFileDiff(allocator, value) };
    if (std.mem.eql(u8, discriminator, "github_tree_comparison")) return .{ .github_tree_comparison = try parseAttachmentGitHubTreeComparison(allocator, value) };
    if (std.mem.eql(u8, discriminator, "github_url")) return .{ .github_url = try parseAttachmentGitHubUrl(allocator, value) };
    if (std.mem.eql(u8, discriminator, "github_file")) return .{ .github_file = try parseAttachmentGitHubFile(allocator, value) };
    if (std.mem.eql(u8, discriminator, "github_snippet")) return .{ .github_snippet = try parseAttachmentGitHubSnippet(allocator, value) };
    if (std.mem.eql(u8, discriminator, "blob")) return .{ .blob = try parseAttachmentBlob(allocator, value) };
    if (std.mem.eql(u8, discriminator, "extension_context")) return .{ .extension_context = try parseAttachmentExtensionContext(allocator, value) };
    return error.InvalidSessionEvent;
}

