            freeAttachmentDirectory(&payload.*, allocator);
        },
        .selection => |*payload| {
            freeAttachmentSelection(&payload.*, allocator);
        },
        .github_reference => |*payload| {
            freeAttachmentGitHubReference(&payload.*, allocator);
        },
        .github_commit => |*payload| {
            freeAttachmentGitHubCommit(&payload.*, allocator);
        },
        .github_release => |*payload| {
            freeAttachmentGitHubRelease(&payload.*, allocator);
        },
        .github_actions_job => |*payload| {
            freeAttachmentGitHubActionsJob(&payload.*, allocator);
        },
        .github_repository => |*payload| {
            freeAttachmentGitHubRepository(&payload.*, allocator);
        },
        .github_file_diff => |*payload| {
            freeAttachmentGitHubFileDiff(&payload.*, allocator);
        },
        .github_tree_comparison => |*payload| {
            freeAttachmentGitHubTreeComparison(&payload.*, allocator);
        },
        .github_url => |*payload| {
            freeAttachmentGitHubUrl(&payload.*, allocator);
        },
        .github_file => |*payload| {
            freeAttachmentGitHubFile(&payload.*, allocator);
        },
        .github_snippet => |*payload| {
            freeAttachmentGitHubSnippet(&payload.*, allocator);
        },
        .blob => |*payload| {
            freeAttachmentBlob(&payload.*, allocator);
        },
        .extension_context => |*payload| {
            freeAttachmentExtensionContext(&payload.*, allocator);
        },
    }
}

