fn isKnownPermissionRequestKind(kind: []const u8) bool {
    if (std.mem.eql(u8, kind, "shell")) return true;
    if (std.mem.eql(u8, kind, "write")) return true;
    if (std.mem.eql(u8, kind, "read")) return true;
    if (std.mem.eql(u8, kind, "mcp")) return true;
    if (std.mem.eql(u8, kind, "url")) return true;
    if (std.mem.eql(u8, kind, "memory")) return true;
    if (std.mem.eql(u8, kind, "custom-tool")) return true;
    if (std.mem.eql(u8, kind, "hook")) return true;
    if (std.mem.eql(u8, kind, "extension-management")) return true;
    if (std.mem.eql(u8, kind, "factory")) return true;
    if (std.mem.eql(u8, kind, "extension-permission-access")) return true;
    if (std.mem.eql(u8, kind, "extension-env-access")) return true;
    return false;
}

fn managedApprovalRequired(data: std.json.ObjectMap) !bool {
    const request = data.get("permissionRequest") orelse return false;
    const object = try payloads.requiredObject(request);
    const value = object.get("managedApprovalRequired") orelse return false;
    return switch (value) {
        .bool => |boolean| boolean,
        else => error.InvalidSessionEvent,
    };
}

fn parseAssistantMessage(
    allocator: std.mem.Allocator,
    data: std.json.ObjectMap,
    raw: *payloads.RawEvent,
) !AssistantMessage {
    var arena = std.heap.ArenaAllocator.init(allocator);
